contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address adr, uint amount) public payable {
        require(adr != address(0));
        require(address(this).balance >= amount);

        uint preBal = address(c).balance;

        // Make the deciding call: multiplicate with value amount
        c.multiplicate{value: amount}(adr);

        uint postBal = address(c).balance;

        // The recipient's balance can only be observed as received Ether.
        // If amount >= preBal, the contract transfers preBal + amount to adr.
        // If amount < preBal, no transfer occurs (no change in c balance).
        // So adr receives either 0 or amount, determined by whether amount >= preBal.
        // We cannot read adr's balance directly, but we know the rule from the
        // state change: if amount >= preBal then postBal == 0, otherwise postBal >= preBal.
        // The general rule: the recipient receives exactly amount iff amount >= preBal,
        // and receives 0 otherwise. Equivalently, the Ether movement out of c is
        // either 0 or amount, and it is amount exactly when preBal <= amount.
        bool transferred = (amount >= preBal);
        assert(transferred ? (postBal == 0) : (postBal >= preBal));
    }

    receive() external payable {}
}

