        c.multiplicate{value: amount}(adr);

        uint postBal = address(c).balance;

        // In all cases, the total Ether accounted for is either:
        // - kept by c: preBal + amount (when amount < preBal)
        // - sent out: adr receives preBal + amount, c balance becomes 0 (when amount >= preBal)
        // So the post-call balance plus the amount sent is at least preBal + amount only if kept,
        // but the amount sent out is exactly preBal + amount, which equals the total available.
        // The invariant: c's balance after the call equals either preBal + amount (if amount < preBal)
        // or 0 (if amount >= preBal), never anything else. Thus postBal == preBal + amount || postBal == 0.
        assert(postBal == preBal + amount || postBal == 0);
    }

    receive() external payable {}
}

